svg.append("text")
  .attr("x", (width + margin.left + margin.right) / 2)
  .attr("y", margin.top - 5)
  .attr("text-anchor", "middle")
  .style("font-size", "18px")
  .text("Dominant Series Annotation");

const g = svg.append("g")
  .attr("transform", `translate(${margin.left},${margin.top})`);

const raw = [
  {x: 0, y: 28, c: 0}, {x: 0, y: 55, c: 1},
  {x: 1, y: 43, c: 0}, {x: 1, y: 91, c: 1},
  {x: 2, y: 81, c: 0}, {x: 2, y: 53, c: 1},
  {x: 3, y: 19, c: 0}, {x: 3, y: 87, c: 1},
  {x: 4, y: 52, c: 0}, {x: 4, y: 48, c: 1},
  {x: 5, y: 24, c: 0}, {x: 5, y: 49, c: 1},
  {x: 6, y: 87, c: 0}, {x: 6, y: 66, c: 1},
  {x: 7, y: 17, c: 0}, {x: 7, y: 27, c: 1},
  {x: 8, y: 68, c: 0}, {x: 8, y: 16, c: 1},
  {x: 9, y: 49, c: 0}, {x: 9, y: 15, c: 1}
];

const categories = [0, 1];
const xValues = [...new Set(raw.map(d => d.x))].sort((a, b) => a - b);

const pivoted = xValues.map(xv => {
  const row = { x: xv };
  categories.forEach(c => {
    const match = raw.find(d => d.x === xv && d.c === c);
    row[c] = match ? match.y : 0;
  });
  return row;
});

const stack = d3.stack().keys(categories).order(d3.stackOrderNone);
const series = stack(pivoted);

const xScale = d3.scalePoint()
  .domain(xValues)
  .range([0, width]);

const yScale = d3.scaleLinear()
  .domain([0, d3.max(series, s => d3.max(s, d => d[1]))]).nice()
  .range([height, 0]);

const color = d3.scaleOrdinal()
  .domain(categories)
  .range(d3.schemeCategory10);

const area = d3.area()
  .curve(d3.curveMonotoneX)
  .x(d => xScale(d.data.x))
  .y0(d => yScale(d[0]))
  .y1(d => yScale(d[1]));

g.selectAll("path.layer")
  .data(series)
  .join("path")
  .attr("class", "layer")
  .attr("d", area)
  .attr("fill", d => color(d.key));

// Add annotations
