    y: 87, // Value for category 0 at x=6
    label: "Series 0 (56.8%)",
    color: color(0)
  }
];

g.append("g")
  .selectAll("annotation")
  .data(annotations)
  .enter().append("g")
  .attr("class", "annotation")
  .each(function(d, i) {
    const g = d3.select(this);

    // Add arrow
    g.append("path")
      .datum(d)
      .attr("d", () => {
        const x = xScale(d.x);
        const y = yScale(d.y);
        return `M${x},${y} L${x + 20},${y} L${x + 15},${y - 5} L${x},${y}`;
      })
      .attr("fill", d.color);

    // Add label
    g.append("text")
      .attr("x", d.x + 25)
      .attr("y", d.y + 5)
      .attr("text-anchor", "start")
      .style("fill", d.color)
      .text(d.label);
  });

g.append("g")
  .attr("transform", `translate(0,${height})`)
  .call(d3.axisBottom(xScale));

g.append("g")
  .call(d3.axisLeft(yScale));
