const width = 400;
const height = 400;
const chartPadding = 40;
const radius = width / 2;

const svg = d3.select("body").append("svg")
  .attr("width", width + chartPadding * 2)
  .attr("height", height + chartPadding * 2)
  .style("background", "white");

const g = svg.append("g")
  .attr("transform", `translate(${chartPadding + radius},${chartPadding + radius})`);

const data = [
  {key: "key-0", value: 19, category: 0},
  {key: "key-1", value: 22, category: 0},
  {key: "key-2", value: 14, category: 0},
  {key: "key-3", value: 38, category: 0},
  {key: "key-4", value: 23, category: 0},
  {key: "key-5", value: 5, category: 0},
  {key: "key-6", value: 27, category: 0},
  {key: "key-0", value: 13, category: 1},
  {key: "key-1", value: 12, category: 1},
  {key: "key-2", value: 42, category: 1},
  {key: "key-3", value: 13, category: 1},
  {key: "key-4", value: 6, category: 1},
  {key: "key-5", value: 15, category: 1},
  {key: "key-6", value: 8, category: 1}
];

const keys = [...new Set(data.map(d => d.key))];
const categories = [...new Set(data.map(d => d.category))];

const angularScale = d3.scalePoint()
  .domain(keys)
  .range([-Math.PI, Math.PI])
  .padding(0.5);

const radialScale = d3.scaleLinear()
  .domain([0, d3.max(data, d => d.value)])
  .range([0, radius]);

const colorScale = d3.scaleOrdinal()
  .domain(categories)
  .range(d3.schemeCategory10);

keys.forEach(key => {
  const angle = angularScale(key);
  g.append("line")
    .attr("x1", 0)
    .attr("y1", 0)
    .attr("x2", radius * Math.cos(angle))
    .attr("y2", radius * Math.sin(angle))
    .attr("stroke", "lightgray")
    .attr("stroke-width", 1);
});

const outerLine = d3.line()
  .x(d => d[0])
  .y(d => d[1])
  .curve(d3.curveLinearClosed);

const outerPoints = keys.map(key => {
  const angle = angularScale(key);
  return [radius * Math.cos(angle), radius * Math.sin(angle)];
});

g.append("path")
  .attr("d", outerLine(outerPoints))
  .attr("fill", "none")
  .attr("stroke", "lightgray")
  .attr("stroke-width", 1);

const catLine = d3.line()
  .x(d => d[0])
  .y(d => d[1])
  .curve(d3.curveLinearClosed);

categories.forEach(cat => {
  const catData = data.filter(d => d.category === cat);
  const points = catData.map(d => {
    const angle = angularScale(d.key);
    const r = radialScale(d.value);
    return [r * Math.cos(angle), r * Math.sin(angle)];
  });

  g.append("path")
    .attr("d", catLine(points))
    .attr("fill", colorScale(cat))
    .attr("fill-opacity", 0.1)
    .attr("stroke", colorScale(cat))
    .attr("stroke-width", 1);
});

data.forEach(d => {
  const angle = angularScale(d.key);
  const r = radialScale(d.value);
  g.append("text")
    .attr("x", r * Math.cos(angle))
    .attr("y", r * Math.sin(angle))
    .attr("text-anchor", "middle")
    .attr("dominant-baseline", "middle")
    .attr("fill", "black")
    .text(d.value);
});

keys.forEach(key => {
  const angle = angularScale(key);
  const x = (radius + 5) * Math.cos(angle);
  const y = (radius + 5) * Math.sin(angle);

  let anchor = "start";
  if (Math.abs(angle) > Math.PI / 2) anchor = "end";

  let baseline = "auto";
  if (angle > 0) baseline = "hanging";
  else if (angle === 0) baseline = "central";

  g.append("text")
    .attr("x", x)
    .attr("y", y)
    .attr("text-anchor", anchor)
    .attr("dominant-baseline", baseline)
    .attr("fill", "black")
    .attr("font-weight", "bold")
    .text(key);
});

// Add comparison labels
const categoryAverages = {};
categories.forEach(cat => {
  const avg = data.filter(d => d.category === cat).reduce((sum, d) => sum + d.value, 0) / data.filter(d => d.category === cat).length;
  categoryAverages[cat] = avg;
});

const maxVal = d3.max(data, d => d.value);
const minVal = d3.min(data, d => d.value);

// Add comparison labels
g.append("g")
  .selectAll("text")
  .data(categories)
  .enter()
  .append("text")
  .each(function(cat, i) {
    const otherCat = categories.filter(c => c !== cat)[0];
    const cat1Avg = categoryAverages[cat];
    const cat2Avg = categoryAverages[otherCat];

    if (Math.abs(cat1Avg - cat2Avg) > 10) {
      const angle = angularScale(cat);
      const x = (radius + 50) * Math.cos(angle);
      const y = (radius + 50) * Math.sin(angle);

      const advantage = cat1Avg > cat2Avg ? `Advantage: Category ${cat}` : `Disadvantage: Category ${cat}`;

      d3.select(this)
        .attr("x", x)
        .attr("y", y)
        .attr("text-anchor", "middle")
        .attr("dominant-baseline", "middle")
        .attr("fill", "black")
        .text(advantage);
    }
  });

// Add central label
g.append("text")
  .attr("x", 0)
  .attr("y", 0)
  .attr("text-anchor", "middle")
  .attr("dominant-baseline", "middle")
  .attr("fill", "black")
  .text("Category Performance");
