{
  "$schema": "https://vega.github.io/schema/vega/v6.json",
  "description": "An example of a space-fulling radial layout for hierarchical data with annotations.",
  "width": 600,
  "height": 600,
  "padding": 5,
  "autosize": "none",

  "data": [
    {
      "name": "tree",
      "url": "data/flare.json",
      "transform": [
        {
          "type": "stratify",
          "key": "id",
          "parentKey": "parent"
        },
        {
          "type": "partition",
          "field": "size",
          "sort": {"field": "value"},
          "size": [{"signal": "2 * PI"}, {"signal": "width / 2"}],
          "as": ["a0", "r0", "a1", "r1", "depth", "children"]
        }
      ]
    },
    {
      "name": "annotations",
      "source": "tree",
      "transform": [
        {
          "type": "calculate",
          "expr": "datum.depth == 0 ? 'flare' : datum.depth == 1 ? 'Packages' : datum.depth == 2 ? 'Sub-packages' : 'Classes'",
          "as": "label"
        },
        {
          "type": "calculate",
          "expr": "datum.depth == 0 ? 0 : datum.depth == 1 ? 1 : datum.depth == 2 ? 2 : 3",
          "as": "zindex"
        }
      ]
    }
  ],

  "scales": [
    {
      "name": "color",
      "type": "ordinal",
      "domain": {"data": "tree", "field": "depth"},
      "range": {"scheme": "tableau20"}
    }
  ],

  "marks": [
    {
      "type": "arc",
      "from": {"data": "tree"},
      "encode": {
        "enter": {
          "x": {"signal": "width / 2"},
          "y": {"signal": "height / 2"},
          "fill": {"scale": "color", "field": "depth"},
          "tooltip": {"signal": "datum.name + (datum.size ? ', ' + datum.size + ' bytes' : '')"}
        },
        "update": {
          "startAngle": {"field": "a0"},
          "endAngle": {"field": "a1"},
          "innerRadius": {"field": "r0"},
          "outerRadius": {"field": "r1"},
          "stroke": {"value": "white"},
          "strokeWidth": {"value": 0.5},
          "zindex": {"value": 0}
        },
        "hover": {
          "stroke": {"value": "red"},
          "strokeWidth": {"value": 2},
          "zindex": {"value": 1}
        }
      }
    },
    {
      "type": "group",
      "from": {"data": "annotations"},
      "encode": {
        "enter": {
          "x": {"signal": "width / 2"},
          "y": {"signal": "height / 2"},
          "zindex": {"field": "zindex"}
        }
      },
      "marks": [
        {
          "type": "text",
          "encode": {
            "enter": {
              "text": {"field": "label"},
              "fill": {"value": "black"},
              "fontSize": {"value": 12},
              "x": {"signal": "width / 2"},
              "y": {
                "expr": "height / 2 + (depth * 50)"
              },
              "align": {"value": "center"}
            }
          }
        }
      ]
    },
    {
      "type": "group",
      "from": {"data": "annotations"},
      "encode": {
        "enter": {
          "x": {"signal": "width / 2"},
          "y": {"signal": "height / 2"},
          "zindex": {"field": "zindex"}
        }
      },
      "marks": [
        {
          "type": "line",
          "encode": {
            "enter": {
              "x1": {"signal": "width / 2"},
              "y1": {"signal": "height / 2"},
              "x2": {"expr": "width / 2 + (depth * 40)"},
              "y2": {"signal": "height / 2"},
              "stroke": {"value": "black"},
              "strokeWidth": {"value": 2}
            }
          }
        },
        {
          "type": "text",
          "encode": {
            "enter": {
              "text": {"field": "label"},
              "fill": {"value": "black"},
              "fontSize": {"value": 12},
              "x": {
                "expr": "width / 2 + (depth * 40) + 10"
              },
              "y": {"signal": "height / 2"},
              "align": {"value": "left"}
            }
          }
        }
      ]
    }
  ],
  "legends": [
    {
      "title": "Depth",
      "items": [
        {"label": "Root (depth 0)", "color": {"scale": "color", "value": 0}},
        {"label": "Packages (depth 1)", "color": {"scale": "color", "value": 1}},
        {"label": "Sub-packages (depth 2)", "color": {"scale": "color", "value": 2}},
        {"label": "Classes (depth 3)", "color": {"scale": "color", "value": 3}}
      ]
    }
  ]
}
